package items_test

import (
	"errors"
	"testing"

	"github.com/mbashem/cftracker/backend/internal/lists/items"
)

// Verify request validation is independent of order loading and position calculation.
// Generated by Codex and not thoroughly checked for correctness.
func TestMoveValidation(t *testing.T) {
	a, b := "A", "B"
	for _, tc := range []struct {
		moves []items.Move
		valid bool
	}{
		{[]items.Move{{ProblemID: a, Before: &b}}, true}, {[]items.Move{{ProblemID: a, After: &b}}, true}, {[]items.Move{{ProblemID: a}}, true},
		{nil, false}, {[]items.Move{{ProblemID: " "}}, false}, {[]items.Move{{ProblemID: a, Before: &a}}, false}, {[]items.Move{{ProblemID: a, Before: &b, After: &b}}, false},
	} {
		err := items.ValidateMoves(tc.moves)
		if (err == nil) != tc.valid {
			t.Fatalf("%+v: %v", tc.moves, err)
		}
	}
	repository := items.NewRepository(nil, 0)
	if _, err := repository.MoveItems(t.Context(), 1, 1, nil); !errors.Is(err, items.ErrInvalidOperation) {
		t.Fatal(err)
	}
}

// Verify ordinary midpoint/append allocation and early redistribution boundaries.
// Generated by Codex and not thoroughly checked for correctness.
func TestPositionBetween(t *testing.T) {
	for _, tc := range []struct {
		left, right, want int64
		rebalance         bool
	}{
		{0, items.PositionGap, items.PositionGap / 2, false},
		{items.PositionGap, 3 * items.PositionGap, 2 * items.PositionGap, false},
		{items.PositionGap, items.MaxPosition, 2 * items.PositionGap, false},
		{1024, 2048, 1536, true},
		{items.MaxPosition - 2, items.MaxPosition, items.MaxPosition - 1, true},
	} {
		got, rebalance := items.PositionBetween(tc.left, tc.right)
		if got != tc.want || rebalance != tc.rebalance {
			t.Fatalf("%+v: %d %v", tc, got, rebalance)
		}
	}
}

// Verify malformed bulk inputs fail before a database dependency is needed.
// Generated by Codex and not thoroughly checked for correctness.
func TestBulkValidationBeforeDatabaseAccess(t *testing.T) {
	repository := items.NewRepository(nil, 0)
	for _, input := range [][]items.ListItem{nil, {{ProblemId: " "}}, {{ProblemId: "A"}, {ProblemId: " A "}}} {
		if _, err := repository.BulkAdd(t.Context(), 1, 1, input); !errors.Is(err, items.ErrInvalidOperation) {
			t.Fatal(err)
		}
	}
	for _, ids := range [][]string{nil, {" "}, {"A", " A "}} {
		if _, err := repository.BulkRemove(t.Context(), 1, 1, ids); !errors.Is(err, items.ErrInvalidOperation) {
			t.Fatal(err)
		}
	}
}
